class Solution {
    public int[] varietyPerWindow(int[] items, int k) {
        int[] out = new int[items.length - k + 1];
        for (int i = 0; i < out.length; i++) {
            Set<Integer> seen = new HashSet<>();
            for (int j = i; j < i + k; j++) seen.add(items[j]);
            out[i] = seen.size();
        }
        return out;
    }
}

