    vector<int> varietyPerWindow(vector<int>& items, int k) {
        vector<int> out;
        for (int i = 0; i + k <= (int) items.size(); i++)
            out.push_back(unordered_set<int>(items.begin() + i, items.begin() + i + k).size());
        return out;
    }
};

