class Solution:
    def varietyPerWindow(self, items: List[int], k: int) -> List[int]:
        count, distinct, out = {}, 0, []
        for i, v in enumerate(items):
            count[v] = count.get(v, 0) + 1
            if count[v] == 1:
                distinct += 1
            if i >= k:
                u = items[i - k]
                count[u] -= 1
                if count[u] == 0:
                    distinct -= 1
            if i >= k - 1:
                out.append(distinct)
        return out

