class Solution {
    public int[] varietyPerWindow(int[] items, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        int distinct = 0;
        int[] out = new int[items.length - k + 1];
        for (int i = 0; i < items.length; i++) {
            if (count.merge(items[i], 1, Integer::sum) == 1) distinct++;
            if (i >= k && count.merge(items[i - k], -1, Integer::sum) == 0) distinct--;
            if (i >= k - 1) out[i - k + 1] = distinct;
        }
        return out;
    }
}

