class Solution {
public:
    vector<int> varietyPerWindow(vector<int>& items, int k) {
        unordered_map<int, int> count;
        int distinct = 0;
        vector<int> out;
        for (int i = 0; i < (int) items.size(); i++) {
            if (++count[items[i]] == 1) distinct++;
            if (i >= k && --count[items[i - k]] == 0) distinct--;
            if (i >= k - 1) out.push_back(distinct);
        }
        return out;
    }
};

